function txt(chars,size,style,color,opts={}){const t=figma.createText();t.fontName={family:'DM Sans',style};t.characters=chars;t.fontSize=size;t.fills=[solid(color,opts.o??1)];if(opts.center){t.textAutoResize='HEIGHT';t.resize(opts.center,t.height);t.textAlignHorizontal='CENTER';}if(opts.right){t.textAutoResize='HEIGHT';t.resize(opts.right,t.height);t.textAlignHorizontal='RIGHT';}return t;}
function frame(w,h,fill,opts={}){const f=figma.createFrame();f.resize(w,h);f.fills=fill===null?[]:[typeof fill==='string'?solid(fill):fill];if(opts.r!==undefined)f.cornerRadius=opts.r;if(opts.stroke){f.strokes=[solid(opts.stroke)];f.strokeWeight=opts.sw??1;}if(opts.name)f.name=opts.name;return f;}
