function recolor(node,h){const s=solid(h);const walk=n=>{if('fills' in n&&Array.isArray(n.fills)&&n.fills.length&&n.fills[0].type==='SOLID'&&n.fills[0].visible!==false)n.fills=[s];if('strokes' in n&&Array.isArray(n.strokes)&&n.strokes.length&&n.strokes[0].type==='SOLID'&&n.strokes[0].visible!==false)n.strokes=[s];if('children' in n)n.children.forEach(walk);};walk(node);}
function mkIcon(key,size,color){const i=comps[key].createInstance();if(size&&size!==24)i.resize(size,size);if(color)recolor(i,color);return i;}
function avat(key,size){const i=comps['av_'+key].createInstance();i.resize(size,size);i.cornerRadius=size/2;return i;}
function card(parent,x,y,w,h){const f=frame(w,h,'FFFFFF',{r:16,stroke:'E8E9F0'});f.x=x;f.y=y;f.effects=[{type:'DROP_SHADOW',color:{r:0.08,g:0.08,b:0.17,a:0.04},offset:{x:0,y:8},radius:24,spread:0,visible:true,blendMode:'NORMAL'}];parent.appendChild(f);return f;}
const tv=figma.createVector();tv.vectorPaths=[{windingRule:'NONE',data:'M 0 40 L 100 40'}];const vnorm=Math.abs(tv.height-1)<3;tv.remove();
function poly(parent,pts,color,wgt){const v=figma.createVector();v.vectorPaths=[{windingRule:'NONE',data:'M '+pts.map(p=>p[0].toFixed(1)+' '+p[1].toFixed(1)).join(' L ')}];v.strokes=[solid(color)];v.strokeWeight=wgt;v.strokeCap='ROUND';v.strokeJoin='ROUND';parent.appendChild(v);let minX=1e9,minY=1e9;for(const p of pts){minX=Math.min(minX,p[0]);minY=Math.min(minY,p[1]);}if(vnorm){v.x=px+minX;v.y=py+minY;}else{v.x=px;v.y=py;}return v;}
